public final class IssuerClientPool {
    private final List<IssuerConnection> connections = new ArrayList<>();

    // a field keeps the handler reachable: the global context only holds a weak reference
    private final Resource cracHandler = new Resource() {
        @Override public void beforeCheckpoint(Context<? extends Resource> c) { closeAll(); }
        @Override public void afterRestore(Context<? extends Resource> c) { openAll(); }
    };

    public IssuerClientPool() {
        openAll();
        Core.getGlobalContext().register(cracHandler);
    }

    private synchronized void openAll() {
        for (int i = 0; i < 20; i++) connections.add(IssuerConnection.open());
    }

    private synchronized void closeAll() {
        connections.forEach(IssuerConnection::close);   // nothing open in the image
        connections.clear();
    }
}

kotlin.src:
class IssuerClientPool {
    private val connections = mutableListOf<IssuerConnection>()

    // a property keeps the handler reachable: the global context only holds a weak reference
    private val cracHandler = object : Resource {
        override fun beforeCheckpoint(c: Context<out Resource>) = closeAll()
        override fun afterRestore(c: Context<out Resource>) = openAll()
    }

    // after cracHandler: Kotlin runs property initializers and init blocks top to bottom
    init {
        openAll()
        Core.getGlobalContext().register(cracHandler)
    }

    @Synchronized private fun openAll() = repeat(20) { connections += IssuerConnection.open() }

    @Synchronized private fun closeAll() {
        connections.forEach { it.close() }              // nothing open in the image
        connections.clear()
    }
}

