final class LedgerConsumer {
    private volatile KafkaConsumer<String, String> consumer = newConsumer();
    private final Resource cracHandler = new Resource() {
        // 1. stop polling, commit, and close the broker connections
        @Override public void beforeCheckpoint(Context<? extends Resource> c) { stopPolling(); consumer.close(); }
        // 2. a new consumer joins the group again after restore
        @Override public void afterRestore(Context<? extends Resource> c) { consumer = newConsumer(); startPolling(); }
    };

    LedgerConsumer() { Core.getGlobalContext().register(cracHandler); }
}

