    private volatile String value = UUID.randomUUID().toString();

    InstanceId() { Core.getGlobalContext().register(this); }   // kept alive by whoever holds InstanceId

    String get() { return value; }

    @Override public void beforeCheckpoint(Context<? extends Resource> c) { }
    // 3. every restored copy gets its own id
    @Override public void afterRestore(Context<? extends Resource> c) { value = UUID.randomUUID().toString(); }
}

