public final class MetricsReporter {
    private ScheduledExecutorService timer;
    private StatsSocket socket;
    // held in a field: the global context only keeps a weak reference
    private final Resource cracHandler = new Resource() {
        @Override
        public void beforeCheckpoint(Context<? extends Resource> c) throws Exception {
            timer.shutdownNow();                                 // 1. no thread sends during the snapshot
            timer.awaitTermination(5, TimeUnit.SECONDS);
            socket.close();                                      // 2. nothing open in the image
        }

        @Override
        public void afterRestore(Context<? extends Resource> c) {
            start();                                             // 3. a new socket and a new schedule
        }
    };

    public MetricsReporter() {
        start();
        Core.getGlobalContext().register(cracHandler);
    }

    private void start() {
        socket = StatsSocket.connect("metrics.internal:8125");
        timer = Executors.newSingleThreadScheduledExecutor();
        timer.scheduleAtFixedRate(this::send, 10, 10, TimeUnit.SECONDS);
    }

    private void send() { socket.write(Counters.snapshot()); }
}

